"use client"

import React, { createContext, useContext, useState, useCallback } from "react"
import { apiClient } from "./api"

type User = {
  name: string
  email: string
  role: string
  agency: string
}

type AuthContextType = {
  user: User | null
  isAuthenticated: boolean
  loginResponse: any | null // Respuesta completa del backend
  login: (userName: string, password: string) => Promise<boolean>
  logout: () => void
}

const AuthContext = createContext<AuthContextType | null>(null)

export function AuthProvider({ children }: { children: React.ReactNode }) {
  const [user, setUser] = useState<User | null>(null)
  const [loginResponse, setLoginResponse] = useState<any | null>(null)

  const login = useCallback(async (userName: string, password: string): Promise<boolean> => {
    try {
      const response = await fetch(apiUrl("/users/login"), {
        method: "POST",
        headers: defaultHeaders,
        body: JSON.stringify({
          userName,
          password,
        }),
      })

      if (!response.ok) {
        const errorData = await response.json().catch(() => ({}))
        const errorMessage = errorData.message || errorData.error || "Error al iniciar sesión"
        throw new Error(errorMessage)
      }

      const data = await response.json()
      
      // Guardar la respuesta completa del backend
      setLoginResponse(data)
      
      // Por ahora, establecer un usuario básico hasta que veamos la estructura de la respuesta
      setUser({
        name: data.name || userName,
        email: data.email || userName,
        role: data.role || "Usuario",
        agency: data.agency || "",
      })

      return true
    } catch (error: any) {
      console.error("Error en login:", error)
      // Re-lanzar el error para que el componente pueda manejarlo
      throw error
    }
  }, [])

  const logout = useCallback(() => {
    setUser(null)
    setLoginResponse(null)
  }, [])

  return (
    <AuthContext.Provider
      value={{
        user,
        isAuthenticated: !!user,
        loginResponse,
        login,
        logout,
      }}
    >
      {children}
    </AuthContext.Provider>
  )
}

export function useAuth() {
  const context = useContext(AuthContext)
  if (!context) {
    throw new Error("useAuth must be used within an AuthProvider")
  }
  return context
}
